typedef unsigned int size_t;
inline void *operator new(size_t, void *p) { return p; }

template <int inst> class __malloc_alloc_template {
public:
  static void *allocate(size_t n);
  static void deallocate(void *p, size_t n);
};

class light_source;
class vector3d { float x, y, z; };
class color { float r, g, b, a; };
typedef float rational_t;
typedef unsigned int u_int;
enum light_flavor_t { LIGHT_FLAVOR_POINT, LIGHT_FLAVOR_SPOT, LIGHT_FLAVOR_DIRECTIONAL, LIGHT_FLAVOR_PARALLELPOINT, NUM_LIGHT_FLAVORS };
class light_properties {
  light_flavor_t flavor;
  color diffuse_color;
  color additive_color;
  rational_t near_range;
  rational_t cutoff_range;
  rational_t recip_cutoff_minus_near;
  u_int lightcat;
  unsigned flags;
};
class light_manager {
public:
  class light_rec {
  public:
    light_source *source;
    vector3d dir_or_pos;
    light_properties props;
    float current_intensity;
    light_rec() : source(0), current_intensity(0.0F) {}
  };
};

template <class T> inline void construct(T *p, const T& value) { new ((void*)p) T(value); }
template <class T> inline void destroy(T *p) { p->~T(); }
template <class T> inline void destroy(T *first, T *last) { while (first != last) { destroy(first); ++first; } }
template <class T> T *uninitialized_copy(T *first, T *last, T *result) { T *cur = result; while (first != last) { construct(cur, *first); ++first; ++cur; } return cur; }
template <class T> T *uninitialized_fill_n(T *first, unsigned int n, const T& value) { T *cur = first; while (n) { construct(cur, value); ++cur; --n; } return cur; }
template <class T> T *copy_backward(T *first, T *last, T *result) { while (first != last) { --result; --last; *result = *last; } return result; }
template <class T> void fill(T *first, T *last, const T& value) { while (first != last) { *first = value; ++first; } }
template <class T> inline const T& max(const T& a, const T& b) { return a < b ? b : a; }

template <class T, class Alloc> class vector {
protected:
  T *_M_start;
  T *_M_finish;
  T *_M_end_of_storage;
  typedef T *iterator;
  typedef unsigned int size_type;
  T *_M_allocate(size_type n) { return (T*)Alloc::allocate(n * sizeof(T)); }
  void _M_deallocate(T *p, size_type n) { Alloc::deallocate(p, n * sizeof(T)); }
public:
  size_type size() const { return size_type(_M_finish - _M_start); }
  void insert(iterator position, size_type n, const T& x);
};

template <class T, class Alloc>
void vector<T, Alloc>::insert(iterator position, size_type n, const T& x)
{
  if (n != 0) {
    if (size_type(_M_end_of_storage - _M_finish) >= n) {
      T x_copy = x;
      const size_type elems_after = _M_finish - position;
      iterator old_finish = _M_finish;
      if (elems_after > n) {
        uninitialized_copy(_M_finish - n, _M_finish, _M_finish);
        _M_finish += n;
        copy_backward(position, old_finish - n, old_finish);
        fill(position, position + n, x_copy);
      } else {
        uninitialized_fill_n(_M_finish, n - elems_after, x_copy);
        _M_finish += n - elems_after;
        uninitialized_copy(position, old_finish, _M_finish);
        _M_finish += elems_after;
        fill(position, old_finish, x_copy);
      }
    } else {
      const size_type old_size = size();
      const size_type len = old_size + max(old_size, n);
      iterator new_start = _M_allocate(len);
      iterator new_finish = new_start;
      new_finish = uninitialized_copy(_M_start, position, new_start);
      new_finish = uninitialized_fill_n(new_finish, n, x);
      new_finish = uninitialized_copy(position, _M_finish, new_finish);
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = new_start;
      _M_finish = new_finish;
      _M_end_of_storage = new_start + len;
    }
  }
}

